; Panel layout and the GAS gauge
; $4e70-$4e90

; Copies the panel layout $2e00-$2ec7 to the screen rows 20-24 ($0720). A byte $ff leaves the cell. The colour of each cell comes from the colour table $4000.
draw_panel
        ldx #$00
draw_panel_cell
        lda panel_layout,x
        cmp #$ff
        beq draw_panel_next
        sta panel_screen,x
        tay
        txa
        pha
        tya
        tax
        lda char_colours,x
        tay
        pla
        tax
        tya
        sta $db20,x
draw_panel_next
        inx
        cpx #$c8
        bcc draw_panel_cell
        rts
